package com.cryptoloan.audit.application;import com.cryptoloan.audit.domain.*;import com.cryptoloan.loan.domain.port.out.LoanPorts.Audit;import java.time.Instant;import java.util.List;import org.springframework.stereotype.Service;@Service public class AuditService implements Audit{private final AuditRepositoryPort repository;public AuditService(AuditRepositoryPort repository){this.repository=repository;}public void record(String actor,String action,String resource,String details){repository.append(new AuditEvent(null,actor,action,resource,details,Instant.now()));}public List<AuditEvent>recent(){return repository.recent();}}
